"""Generate the operator PDF and its Markdown source; no credentials embedded."""
from pathlib import Path
from html import escape
import shutil
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Preformatted, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT.parent/"PDecision/docs"
OUT.mkdir(exist_ok=True)
styles=getSampleStyleSheet()
fonts=Path("C:/Windows/Fonts")
pdfmetrics.registerFont(TTFont("Guide",str(fonts/"segoeui.ttf")))
pdfmetrics.registerFont(TTFont("GuideBold",str(fonts/"segoeuib.ttf")))
styles.add(ParagraphStyle(name="GuideBody",fontName="Guide",fontSize=10,leading=15,spaceAfter=9,textColor=colors.HexColor("#243b35")))
styles.add(ParagraphStyle(name="GuideTitle",fontName="GuideBold",fontSize=23,leading=28,spaceAfter=17,textColor=colors.HexColor("#285d47")))
styles.add(ParagraphStyle(name="GuideHeading",fontName="GuideBold",fontSize=13,leading=18,spaceBefore=8,spaceAfter=8,textColor=colors.HexColor("#285d47")))
styles.add(ParagraphStyle(name="GuideCode",fontName="Courier",fontSize=8,leading=12,spaceBefore=5,spaceAfter=12,backColor=colors.HexColor("#f0f4ef"),borderPadding=8))
story=[];md=[]
def title(s):story.append(Paragraph(escape(s),styles["GuideTitle"]));md.append("# "+s+"\n")
def h(s):story.append(Paragraph(escape(s),styles["GuideHeading"]));md.append("## "+s+"\n")
def p(s):story.append(Paragraph(escape(s),styles["GuideBody"]));md.append(s+"\n")
def code(s):story.append(Preformatted(s,styles["GuideCode"]));md.append("```\n"+s+"\n```\n")
def link(label,url):story.append(Paragraph('<link href="'+url+'" color="#285d47">'+escape(label)+'</link>',styles["GuideBody"]));md.append('['+label+']('+url+')\n')
def page():story.append(PageBreak())
title("New machine installation")
p("PokerSuite agent 1.0.7 | Windows x64 | 29 October 2026")
h("What the agent installs")
p("A new PC does not need a source checkout, Git or Python. Install Windows prerequisites, register and enroll the PC, and provide its protected runtime settings. After you schedule its first installation on the backoffice Updates page, the agent downloads the signed release containing PDecision and the PyInstaller-packaged PokerController, then starts both applications.")
p("Installing the agent alone does not choose a release or authorize a PC. An operator selects the release and schedules the installation from the website. Application credentials are provisioned separately from the updater token.")
h("Before starting")
p("1. Use a Windows x64 PC and the Windows account that will run the applications. Keep that account signed in during operation. The agent starts at user logon; it is not a service that starts before anyone signs in.")
p("2. Install the x64 .NET 8 Desktop Runtime AND ASP.NET Core Runtime. PDecision needs both frameworks; the Desktop Runtime also supplies the base .NET runtime.")
p("3. Install SQL Server Express LocalDB for local player-statistics databases. Install SQL Server ODBC Driver 17, or Driver 18 with SCHEDULE_ODBC_DRIVER set accordingly in the worker settings.")
p("4. Allow the network connections required by the existing PokerSuite setup: backoffice and Azure Blob HTTPS, Azure SQL, the poker platform and solver/resource services. Do not expose the local decision API to the Internet. Allow sufficient disk space for strategy resources, local databases and two release copies.")
link("Microsoft: .NET 8 runtime downloads","https://dotnet.microsoft.com/en-us/download/dotnet/8.0")
link("Microsoft: SQL Server Express LocalDB","https://learn.microsoft.com/en-us/sql/database-engine/configure-windows/sql-server-express-localdb")
link("Microsoft: SQL Server ODBC driver downloads","https://learn.microsoft.com/en-us/sql/connect/odbc/download-odbc-driver-for-sql-server")
page()
title("1. Register and authenticate the PC")
h("Collect the actual adapter MAC address")
p("On the new PC, open PowerShell and run this command. Send the active physical Ethernet or Wi-Fi adapter MAC address and the PC name to your administrator. Keep that adapter present; a copied enrollment for another PC will be rejected.")
code("hostname\nGet-NetAdapter -Physical | Select-Object Name, MacAddress, Status")
h("Administrator: create the machine registration")
p("The current backoffice can configure and enroll registered machines; it does not create new machine registrations. An administrator must register the MAC in dbo.CustomerMachine for the correct active customer, casino and platform. The existing dbo.Machine_Upsert procedure in PDecision/sql/CustomerMachines.sql performs registration.")
p("Also add the machine to scheduler.MachineAssignment for its site, with the intended MaxEntries and IsEnabled, and add backoffice.MachineMetadata and backoffice.MachineAllowedSite records. The site and machine must belong to the same customer. Use the new MachineId, not the ID of a different PC.")
h("Operator: enroll through the website")
p("Sign in with an operator account. Open Updates for the correct customer/site and choose Enroll / replace updater for the new machine. Save the downloaded agent-machine-ID.json. Download and extract the updater installer ZIP from the same page. Use installer 1.0.7 or later for fresh installations.")
link("Open Backoffice Updates","https://lively-rock-032158003.4.azurestaticapps.net/#updates")
h("Two independent authentication checks")
p("Updater: the downloaded JSON contains a private machine-scoped API token and trusted release-signing public keys. The agent checks the enrolled MAC locally; the server checks the token and registered machine/site. The token does not grant a website login.")
p("PDecision: its own restricted database login reads the active machine/customer registration by MAC. PokerController uses its provisioned worker SQL login and machine/site assignment. A legacy Authentication.txt is not required by the current PDecision build. Registration and runtime settings are still required.")
p("Keep enrollment and runtime-settings files private. Do not share them between customers, commit them to source control or include them in release ZIPs. Re-enrollment replaces the updater token and invalidates the previous enrollment.")
page()
title("2. Install the agent on a fresh PC")
h("Obtain two settings files from the administrator")
p("pdecision.json: the approved appsettings.json for this customer, including Database.ConnectionString and the local Api configuration. The default health address is http://127.0.0.1:5005/api/health; it must match DecisionHealthUrl in the enrollment JSON.")
p("worker-env.json: an object containing SCHEDULE_SQL_CONNECTION_STRING (native ODBC) or SqlConnectionString (ADO.NET). SCHEDULE_ODBC_DRIVER is optional. Use the dedicated worker login, not an administrator login. These settings are needed after reboot because the scheduled task does not inherit a developer terminal's private environment.")
p("Example structure only; the administrator supplies real restricted credentials:")
code('{\n  "SCHEDULE_SQL_CONNECTION_STRING": "<restricted ODBC connection>"\n}')
h("Run the installer")
p("Extract the ZIP to a local setup folder and place the enrollment and settings files beside Install-Updater.ps1. Open PowerShell in that folder as the intended Windows account. Replace 7 below with your actual machine ID. If C:\\PokerSuite cannot be created, have the administrator grant this account access to that folder.")
code('powershell.exe -NoProfile -ExecutionPolicy Bypass `\n  -File .\\Install-Updater.ps1 `\n  -ConfigPath .\\agent-machine-7.json `\n  -FreshInstall `\n  -DecisionSettingsPath .\\pdecision.json `\n  -WorkerSettingsPath .\\worker-env.json')
p("The installer saves protected settings under C:\\PokerSuite\\Managed\\config, installs the agent under C:\\PokerSuite\\Updater and creates the scheduled task PokerSuite Updater ID. It starts the agent immediately. You do not need to install PDecision or PokerController manually.")
h("Schedule the first application installation")
p("Wait for the agent to appear connected on Updates. Select a published release and this machine, then schedule the update now or choose a later start time. A fresh machine has no sessions to drain. The task verifies the download, installs both executables, starts PDecision and waits for ready, then starts PokerController and checks its version and heartbeat. First startup can take time while PDecision synchronizes resources and creates databases.")
p("After successful installation, scheduling resumes if the site and machine are enabled and the current schedule requires entries. Traffic follows normal gradual scheduling. Keep the private setup files in protected storage or remove their temporary copies after installation.")
page()
title("3. Startup and automatic recovery")
h("What happens at Windows logon")
p("Windows Task Scheduler starts the agent when the enrolled user signs in. The agent launches the installed PDecision first, waits for its ready health response, then launches PokerController. A network connection is needed for the first installation and normal poker operation.")
h("What happens when an application exits")
p("For an installed managed release, the agent checks the recorded process identity. If PDecision or PokerController is no longer running, it attempts a restart, in the same startup order. It also does this while an update is restoring traffic. Failed restart attempts are paced with a 90-second retry interval; PDecision readiness can take up to two hours and controller startup up to 5 minutes.")
p("The last server-approved supervision mode is stored locally. After normal supervision has been enabled, it continues through a temporary backoffice outage. Intentional update shutdowns disable supervision, and an unfinished installation journal blocks ordinary restarts so they cannot race installation or rollback.")
p("This is process-exit recovery. An application that stays alive but becomes unhealthy is reported unhealthy and prevents the rollout from advancing; the agent does not force-kill it. Similarly, it does not kill unrelated applications with the same name. Do not manually launch duplicate copies.")
h("Updates and failures")
p("Existing machines finish one bot session at a time before update shutdown. Downloads are authenticated with the pinned RSA signing key and verified by SHA-256. A startup failure attempts rollback when a previous release exists. On a first installation there is no older release to restore; failure pauses the rollout for review instead.")
p("The next machine waits for health and traffic recovery. Other machines keep their schedules. To intentionally keep applications stopped, disable the updater scheduled task and stop the updater first; stopping only an application allows the agent to restart it. Do not interrupt the agent during installation or rollback.")
h("Where files are stored")
code('C:\\PokerSuite\\Updater\\agent.json\nC:\\PokerSuite\\Managed\\config\\pdecision.json\nC:\\PokerSuite\\Managed\\config\\worker-env.json\nC:\\PokerSuite\\Managed\\versions\\<release-id>\nC:\\PokerSuite\\Managed\\runs\\<run-id>\nC:\\PokerSuite\\Managed\\updater.log')
page()
title("4. Verify and troubleshoot")
h("Installation acceptance checks")
p("On Updates, confirm a recent agent heartbeat, the intended installed release and healthy applications. On Machines, confirm the machine is online and both application versions are reported. A successful task can remain in traffic recovery while entries increase gradually; that does not mean the application installation is still running.")
code('Get-ScheduledTask -TaskName "PokerSuite Updater 7"\nGet-Process PDecision,PokerController -ErrorAction SilentlyContinue\nInvoke-RestMethod http://127.0.0.1:5005/api/health\nGet-Content C:\\PokerSuite\\Managed\\updater.log -Tail 20')
p("Expected health: status ready and the selected PDecision version. The current worker's run folder is recorded in Managed\\active.json. Its status.json contains the controller version and heartbeat; worker.log contains startup and command details. PDecision logs are under C:\\PokerSuite\\Logs.")
h("Common problems")
p("Agent absent: check that the intended Windows user is logged in, the scheduled task exists, .NET is installed and the enrolled MAC is present. Check updater.log. HTTP 401 normally means the token is invalid or has been replaced; another active updater instance can cause HTTP 409.")
p("PDecision not ready: check machine/customer activation and MAC registration, Database.ConnectionString, network access, LocalDB and resource initialization. The health response and PDecision log give the reason. Allow initial resource synchronization time.")
p("Controller fails: check worker-env.json, ODBC driver selection, restricted SQL permissions and machine/site assignment. An ODBC Driver 18-only PC needs SCHEDULE_ODBC_DRIVER set to ODBC Driver 18 for SQL Server if the ADO.NET-style setting is used, or that driver named directly in the native ODBC connection string.")
p("Fresh installation remains queued: confirm the agent is connected and the customer has no paused rollout blocking later work. A machine with open session or entry records is treated as an existing machine and cannot bypass draining by claiming to be a fresh installation.")
h("Enroll an existing installation instead")
p("For a running legacy Python worker, omit -FreshInstall and provide -ControllerRoot. The installer records the running process identities and preserves the machine settings. For an already managed installation it preserves active.json. Stop only the updater before replacing its binaries, and only when no installation/rollback is active. Never use -FreshInstall over an existing managed installation.")
p("Agent upgrades are separate from application releases. Install the newer updater ZIP on each PC under controlled conditions; scheduling a PDecision/PokerController release does not replace the updater itself.")
page()
title("Administrator registration example")
p("Use this template in Azure SQL pokerdb with an administrator account. It is for a new Nenad / Evenbet PC on site 1. Replace the MAC and hostname, verify the customer/site and entry capacity, and adjust the casino/platform for other deployments. This is not run by the agent. The same script is saved as register-new-machine.sql beside this PDF.")
code((OUT/"register-new-machine.sql").read_text())
p("After registration, use the returned MachineId when enrolling on Updates. Provision the approved restricted PDecision and worker settings privately; registration does not generate database passwords. The operator can then follow pages 2-5 to enroll, install and verify the new PC.")
