 canvas.saveState();canvas.setFont("Guide",8);canvas.setFillColor(colors.HexColor("#65766e"));canvas.drawString(42,27,"PokerSuite | New machine setup | Agent 1.0.7");canvas.drawRightString(A4[0]-42,27,str(doc.page));canvas.restoreState()
